@isTest
private class LSOAccessLineTriggerHandlerTest {

    private static User createTestUser(String uniqueKey) {
        Profile p = [SELECT Id FROM Profile WHERE Name = 'Standard User' LIMIT 1];
        User u = new User(
            FirstName = 'Test',
            LastName = 'User ' + uniqueKey,
            Alias = uniqueKey.left(8),
            Email = uniqueKey + '@example.test.com',
            Username = uniqueKey + '@example.test.com.lsotest',
            EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US',
            LocaleSidKey = 'en_US',
            TimeZoneSidKey = 'America/Chicago',
            ProfileId = p.Id
        );
        insert u;
        return u;
    }

    @isTest
    static void testDuplicateCountryWithinSameRequestIsBlocked() {
        User targetUser = createTestUser('line1' + System.currentTimeMillis());
        User owner = createTestUser('own1' + System.currentTimeMillis());

        Country_Group_Mapping__c mapping = new Country_Group_Mapping__c(
            Name = 'Wonderland',
            Public_Group_Name__c = 'Wonderland_Access_' + System.currentTimeMillis(),
            Country_Access_Owner__c = owner.Id,
            Active__c = true
        );
        insert mapping;

        LSO_Cross_Country_Access_Request__c header = new LSO_Cross_Country_Access_Request__c(
            Requested_User__c = targetUser.Id,
            Business_Justification__c = 'Need access.'
        );
        insert header;

        LSO_CCAR_Line__c line1 = new LSO_CCAR_Line__c(
            LSO_Cross_Country_Access_Request__c = header.Id,
            Country__c = mapping.Id
        );
        insert line1;

        LSO_CCAR_Line__c line2 = new LSO_CCAR_Line__c(
            LSO_Cross_Country_Access_Request__c = header.Id,
            Country__c = mapping.Id
        );

        Boolean blocked = false;
        try {
            insert line2;
        } catch (DmlException e) {
            blocked = true;
        }
        System.assert(blocked, 'A second line for the same country on the same request should be blocked.');
    }

    @isTest
    static void testDuplicateCountryAcrossRequestsIsBlockedUnlessRejected() {
        User targetUser = createTestUser('line2' + System.currentTimeMillis());
        User owner = createTestUser('own2' + System.currentTimeMillis());

        Country_Group_Mapping__c mapping = new Country_Group_Mapping__c(
            Name = 'Genovia',
            Public_Group_Name__c = 'Genovia_Access_' + System.currentTimeMillis(),
            Country_Access_Owner__c = owner.Id,
            Active__c = true
        );
        insert mapping;

        LSO_Cross_Country_Access_Request__c header1 = new LSO_Cross_Country_Access_Request__c(
            Requested_User__c = targetUser.Id,
            Business_Justification__c = 'First request.'
        );
        insert header1;

        LSO_CCAR_Line__c line1 = new LSO_CCAR_Line__c(
            LSO_Cross_Country_Access_Request__c = header1.Id,
            Country__c = mapping.Id
        );
        insert line1;

        // Resolve header1 so a second header can be created for the same user.
        line1.Line_Status__c = 'Approved';
        update line1;
        header1.Status__c = 'Fully Approved';
        update header1;

        LSO_Cross_Country_Access_Request__c header2 = new LSO_Cross_Country_Access_Request__c(
            Requested_User__c = targetUser.Id,
            Business_Justification__c = 'Second request, different submission.'
        );
        insert header2;

        // Same country, different header: still blocked because line1 is Approved, not Rejected.
        LSO_CCAR_Line__c line2 = new LSO_CCAR_Line__c(
            LSO_Cross_Country_Access_Request__c = header2.Id,
            Country__c = mapping.Id
        );
        Boolean blockedWhileApproved = false;
        try {
            insert line2;
        } catch (DmlException e) {
            blockedWhileApproved = true;
        }
        System.assert(blockedWhileApproved, 'An approved line elsewhere for the same country should still block a duplicate.');

        // Once the original line is Rejected, the same country can be requested again.
        line1.Line_Status__c = 'Rejected';
        update line1;

        Test.startTest();
        LSO_CCAR_Line__c line3 = new LSO_CCAR_Line__c(
            LSO_Cross_Country_Access_Request__c = header2.Id,
            Country__c = mapping.Id
        );
        insert line3;
        Test.stopTest();

        System.assertNotEquals(null, line3.Id, 'A rejected line should no longer block a new request for the same country.');
    }
}
